"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["90830"],{92538(e){e.exports=JSON.parse('{"tag":{"label":"Hamsters","permalink":"/docs/tags/hamsters","allTagsPath":"/docs/tags","count":25,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Hamsters/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Hamsters","description":"An overview of the most common health issues affecting pet hamsters, including the critical emergency of wet tail, respiratory infections, and common tumors.","permalink":"/docs/Hamsters/illnesses-and-conditions/common-health-issues"},{"id":"Hamsters/health-and-wellness/dental-health","title":"Dental Health in Hamsters","description":"A guide to dental health in hamsters, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the importance of providing appropriate chew toys.","permalink":"/docs/Hamsters/health-and-wellness/dental-health"},{"id":"Hamsters/illnesses-and-conditions/diabetes-in-hamsters","title":"Diabetes in Pet Hamsters","description":"A comprehensive guide to diabetes in hamsters \u2014 which breeds are most at risk, signs and symptoms, diagnosis, and management strategies.","permalink":"/docs/Hamsters/illnesses-and-conditions/diabetes-in-hamsters"},{"id":"general-care/health-and-medical/entropion","title":"Entropion in Small Pets","description":"A comprehensive guide to entropion \u2014 the inward rolling of the eyelid \u2014 in small pets including rabbits, hamsters, guinea pigs, and rats. Covers causes, clinical signs, diagnosis, and treatment options.","permalink":"/docs/general-care/health-and-medical/entropion"},{"id":"Hamsters/care-and-husbandry/essential-supplies","title":"Essential Supplies for Pet Hamsters","description":"A complete checklist of essential supplies needed to create a safe, comfortable, and stimulating environment for a pet hamster.","permalink":"/docs/Hamsters/care-and-husbandry/essential-supplies"},{"id":"Hamsters/health-and-wellness/eye-and-vision-issues","title":"Eye & Vision Issues in Hamsters","description":"A guide to common eye and vision issues in hamsters, including infections, age-related problems like cataracts, and serious conditions like glaucoma.","permalink":"/docs/Hamsters/health-and-wellness/eye-and-vision-issues"},{"id":"Hamsters/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Hamsters","description":"A guide to gastrointestinal (GI) health in hamsters, with a focus on the causes of diarrhea and the serious, often fatal condition known as Wet Tail.","permalink":"/docs/Hamsters/health-and-wellness/gi-health"},{"id":"Hamsters/care-and-husbandry/grooming","title":"Grooming Your Pet Hamster","description":"A guide to hamster grooming, focusing on their natural self-cleaning abilities and providing instructions for sand baths and occasional assistance.","permalink":"/docs/Hamsters/care-and-husbandry/grooming"},{"id":"Hamsters/getting-started/hamster-basic-care","title":"Hamster Basic Care","description":"Hamsters are popular pets, known for their chubby cheeks and love of running on their wheel. While they are small, they still require consistent care to thrive. This guide covers the daily, weekly, and monthly tasks needed to keep your hamster healthy and happy.","permalink":"/docs/Hamsters/getting-started/hamster-basic-care"},{"id":"Hamsters/care-and-husbandry/habitat","title":"Hamster Habitat & Housing","description":"A hamster\'s cage is its entire world. Learn what enclosure sizes, bedding depths, enrichment, and environmental conditions your hamster truly needs \u2014 and which popular products to avoid.","permalink":"/docs/Hamsters/care-and-husbandry/habitat"},{"id":"Hamsters/care-and-husbandry/nutrition","title":"Hamster Nutrition","description":"Providing a proper diet is fundamental to your hamster\'s health. Hamsters are omnivores and require a balanced diet of pellets, supplemented with small amounts of fresh foods. Understanding what to...","permalink":"/docs/Hamsters/care-and-husbandry/nutrition"},{"id":"Hamsters/illnesses-and-conditions/hamster-polyomavirus","title":"Hamster Polyomavirus (HaPyV)","description":"A comprehensive guide to Hamster Polyomavirus (HaPyV) \u2014 the virus responsible for trichoepitheliomas (skin tumors) and lymphoma in Syrian hamsters. Covers causes, clinical signs, diagnosis, and what to do if your hamster is affected.","permalink":"/docs/Hamsters/illnesses-and-conditions/hamster-polyomavirus"},{"id":"Hamsters/care-and-husbandry/wheels-vs-saucers","title":"Hamster Wheels and Saucers: Size, Safety, and What the Evidence Says","description":"A comprehensive guide to choosing the right wheel or saucer for your hamster \u2014 covering minimum sizes for each species, the risks of wire mesh and saucers, and what the science says about spinal health.","permalink":"/docs/Hamsters/care-and-husbandry/wheels-vs-saucers"},{"id":"Hamsters/health-and-wellness/home-health-care","title":"Home Health Care for Pet Hamsters","description":"A comprehensive guide to performing regular at-home health checks for your pet hamster to detect early signs of illness and ensure their well-being.","permalink":"/docs/Hamsters/health-and-wellness/home-health-care"},{"id":"Hamsters/getting-started/is-a-hamster-right-for-me","title":"Is a Hamster Right for Me and My Family?","description":"Hamsters are often purchased as a first pet for young children, but the reality of hamster ownership frequently surprises families who aren\'t prepared. They are fascinating, complex animals \u2014 but...","permalink":"/docs/Hamsters/getting-started/is-a-hamster-right-for-me"},{"id":"Hamsters/breeds-and-genetics/know-your-hamster-breeds","title":"Know Your Hamster Breeds","description":"An overview of the five hamster species commonly kept as pets, with their key traits, size, and care considerations.","permalink":"/docs/Hamsters/breeds-and-genetics/know-your-hamster-breeds"},{"id":"general-care/health-and-medical/microphthalmia","title":"Microphthalmia in Small Pets","description":"A comprehensive guide to microphthalmia (abnormally small eyes) in small pets, covering its genetic causes, species-specific presentations in rabbits, ferrets, hamsters, guinea pigs, and rats, and how to manage affected animals.","permalink":"/docs/general-care/health-and-medical/microphthalmia"},{"id":"Hamsters/health-and-wellness/parasites","title":"Parasites in Hamsters","description":"A guide to parasites affecting hamsters, with a focus on Demodex mites, which often signal an underlying health problem, as well as the fungal infection ringworm.","permalink":"/docs/Hamsters/health-and-wellness/parasites"},{"id":"Hamsters/care-and-husbandry/proper-handling","title":"Proper Handling of Pet Hamsters","description":"A step-by-step guide to taming and safely handling your pet hamster, building a bond of trust through patience and positive reinforcement.","permalink":"/docs/Hamsters/care-and-husbandry/proper-handling"},{"id":"Hamsters/health-and-wellness/respiratory-issues","title":"Respiratory Issues in Hamsters","description":"A guide to respiratory infections in hamsters, covering the common causes like bedding and stress, the signs of illness, and the importance of prompt veterinary care.","permalink":"/docs/Hamsters/health-and-wellness/respiratory-issues"},{"id":"Hamsters/illnesses-and-conditions/seasonal-alopecia","title":"Seasonal Alopecia in Hamsters","description":"A guide to seasonal alopecia in hamsters, a harmless, hormone-driven hair loss typically seen in male Syrian hamsters during the winter months.","permalink":"/docs/Hamsters/illnesses-and-conditions/seasonal-alopecia"},{"id":"Hamsters/breeds-and-genetics/sexing-your-hamster","title":"Sexing Your Pet Hamster","description":"A guide to accurately determining the sex of a pet hamster by examining key anatomical differences, including anogenital distance and physical features.","permalink":"/docs/Hamsters/breeds-and-genetics/sexing-your-hamster"},{"id":"Hamsters/health-and-wellness/understanding-hamster-behavior","title":"Understanding Hamster Behavior: A Guide for Owners","description":"Hamsters are solitary, nocturnal animals with a fascinating range of behaviors. Learning to read their body language is essential for building trust and keeping them healthy.","permalink":"/docs/Hamsters/health-and-wellness/understanding-hamster-behavior"},{"id":"Hamsters/illnesses-and-conditions/wet-tail","title":"Wet Tail in Hamsters","description":"An essential guide to wet tail in hamsters, a serious and often fatal diarrheal disease, explaining its causes, signs, and the critical need for immediate veterinary action.","permalink":"/docs/Hamsters/illnesses-and-conditions/wet-tail"}],"unlisted":false}}')}}]);